 analysis=load(ANA/'V4_REPAIRED_PAIRED_ANALYSIS.json'); score=load(ANA/'V4_REFERENCE_PROXY_SCORECARD.json'); parser=load(SEL/'V1_HTML_TEXT_REPAIR_MANIFEST.json'); integrity=load(SEL/'V2_REPAIRED_SELECTOR_INTEGRITY.json'); reader=load(BASE/'03_reader/html_text_repair_1/V3_READER_RUN_SUMMARY.json')
