 manifest={'manifest_type':'E11V_HTML_TEXT_REPAIR_APPEND_ONLY_PROVENANCE','repair_id':'E11V-HTML-TEXT-REPAIR-1','artifact_count':len(files),'artifacts':files,'original_e11v_artifacts_preserved':True,'holdout_accessed':False,'jev_calls':0,'paid_api_calls':0}
 (CLO/'E11V_HTML_TEXT_REPAIR_PROVENANCE.json').write_text(json.dumps(manifest,indent=2)+'\n')
 print(json.dumps({'gate':gate['gate'],'repair_artifacts':len(files),'reader':reader,'tests':tests},indent=2))
